//! T3434 Rule 24 retirement list. A retired system's Rust path is mandatory: its A/B
//! env switch no longer selects the lifted body. The lifted bodies stay in the lift as
//! the reference oracle; `--features lifted-oracle` restores the switch.

pub const RETIRED: &[&str] = &["story-sequencer"];

/// False when `system` is retired (and this is not an oracle build).
pub fn lifted_selectable(system: &str) -> bool {
    cfg!(feature = "lifted-oracle") || !RETIRED.contains(&system)
}

#[cfg(test)]
mod tests {
    #[test]
    fn unretired_systems_stay_selectable() {
        assert!(super::lifted_selectable("t3434-not-a-system"));
        for system in super::RETIRED {
            let oracle = cfg!(feature = "lifted-oracle");
            assert_eq!(super::lifted_selectable(system), oracle);
        }
    }
}
